// Multi-Form & Campaign Routing Registry (Strict Form Filter)
const registry = {
  "1044971085049692": { campaignName: "Silver Saphire", tableName: "Silver Saphire" },
  "900221056143338": { campaignName: "Navkarmik", tableName: "Navkarmik" }
};

const items = $input.all();
const results = [];

for (const item of items) {
  const body = item.json.body || item.json;

  // Extract Form ID
  let formId = body.form_id || (body.entry && body.entry[0]?.changes[0]?.value?.form_id) || "";
  formId = String(formId).trim();

  // Strict Registry Filter Check
  if (!registry[formId]) {
    continue; // Ignore leads from unregistered form IDs
  }

  const campaignName = registry[formId].campaignName;
  const tableName = registry[formId].tableName;

  // Field Normalization & Extraction
  const fieldData = body.field_data || (body.entry && body.entry[0]?.changes[0]?.value?.field_data) || [];

  let rawPhone = "";
  let rawName = "";
  let rawConfig = "";
  const leadId = body.leadgen_id || (body.entry && body.entry[0]?.changes[0]?.value?.leadgen_id) || Date.now().toString().slice(-6);

  if (Array.isArray(fieldData)) {
    for (const f of fieldData) {
      const name = String(f.name || "").toLowerCase();
      const val = Array.isArray(f.values) ? f.values.join(", ") : String(f.values || "");

      if (name.includes("phone") || name.includes("mobile") || name.includes("contact")) rawPhone = val;
      else if (name.includes("full name") || name.includes("name")) rawName = val;
      else if (name.includes("configuration") || name.includes("unit") || name.includes("bhk") || name.includes("looking for")) rawConfig = val;

      if (!rawConfig && (val.toLowerCase().includes("bhk") || val.toLowerCase().includes("jodi"))) rawConfig = val;
    }
  }

  // 1. Phone Normalization (12-digit Indian 91XXXXXXXXXX)
  let digits = (rawPhone || "").replace(/\D/g, "");
  const mobileMatch = digits.match(/[6-9]\d{9}$/);
  if (mobileMatch) digits = "91" + mobileMatch[0];
  else if (digits.length === 10) digits = "91" + digits;
  else if (digits.length > 12 && digits.startsWith("91")) digits = digits.slice(0, 12);
  if (!digits) digits = "910000000000";

  // 2. Full Name Extractor & Fallback
  let fullName = (rawName || "").trim();
  const dummyTerms = ["test", "dummy", "n/a", "none", ""];
  if (dummyTerms.includes(fullName.toLowerCase())) {
    fullName = `FB Prospect (#${leadId})`;
  }

  // 3. Property Configuration
  let propertyType = (rawConfig || "2 BHK").toUpperCase().replace(/\s+/g, " ");
  if (propertyType.includes("JODI")) propertyType = "JODI OPTION";

  // 4. Formatted WhatsApp Message
  const whatsappMessage = `🚨 *NEW LEAD RECEIVED* 🚨\n\n📋 *Campaign Name:* ${campaignName}\n📌 *Meta Form ID:* ${formId}\n\n👤 *Customer Name:* ${fullName}\n📱 *Phone Number:* +${digits}\n🏢 *Configuration:* ${propertyType}\n📁 *Saved To Table:* ${tableName}`;

  results.push({
    json: {
      formId,
      campaignName,
      tableName,
      leadId,
      fullName,
      phoneNumber: digits,
      propertyType,
      whatsappMessage,
      adminNumbers: ["+919892749953", "+917738382905"]
    }
  });
}

return results;
